def predict(df,p):
    def one(dose,ts):
        k=p['ke0']; a=dose/50; ke=0.1
        Ce=a*k/(k-ke)*(np.exp(-ke*ts)-np.exp(-k*ts))
        Ce=np.maximum(Ce,0)
        return p['E0']+p['Emax']*Ce**p['n']/(p['EC50']**p['n']+Ce**p['n'])
    return per_dose(df,one)

